const CACHE_NAME = 'elvosolar-v9';

// OFFLINE OBRAZOVKA — servisuje sa ked navigacia zlyha bez siete.
// Logo je vlozene ako base64 + pozadie je cisty CSS → funguje uplne bez siete.
const OFFLINE_HTML = `<!doctype html>
<html lang="sk">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="theme-color" content="#02040a">
<title>ElvoControll — offline</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { height: 100%; }
  body {
    position: relative;
    background: linear-gradient(160deg, #0e1a35 0%, #061224 45%, #020617 100%);
    color: #e2e8f0;
    font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
    display: flex; align-items: center; justify-content: center;
    padding: 24px; text-align: center; overflow: hidden;
  }
  /* FOTOVOLTICKA FOTKA ako podklad — vlozene priamo (base64), funguje offline */
  body::before {
    content: ''; position: absolute; inset: 0; z-index: 0; pointer-events: none;
    background-image: url('data:image/jpeg;base64,');
    background-size: cover; background-position: center;
    opacity: 0.5;
  }
  /* Tmave prekrytie — aby zostal text citatelny nad fotkou */
  body::after {
    content: ''; position: absolute; inset: 0; z-index: 0; pointer-events: none;
    background:
      radial-gradient(1200px 700px at 80% -15%, rgba(34,211,238,0.14), transparent 60%),
      linear-gradient(160deg, rgba(6,10,20,0.55) 0%, rgba(2,6,23,0.82) 55%, rgba(2,6,23,0.95) 100%);
  }
  .wrap { position: relative; z-index: 1; max-width: 420px; width: 100%; }
  .logo { width: 96px; height: auto; margin: 0 auto 22px; display: block; filter: drop-shadow(0 6px 24px rgba(6,182,212,0.35)); }
  h1 { font-size: 21px; font-weight: 700; margin-bottom: 8px; letter-spacing: .3px; }
  p  { font-size: 14px; color: #9fb0c4; line-height: 1.55; }
  .hint { margin-top: 10px; font-size: 12.5px; color: #64748b; }
  button {
    margin-top: 22px; width: 100%; padding: 13px 16px;
    font-size: 15px; font-weight: 600; font-family: inherit;
    color: #020617; background: linear-gradient(90deg,#22d3ee,#34d399);
    border: 0; border-radius: 12px;
    cursor: pointer; -webkit-tap-highlight-color: transparent;
  }
  button:active { transform: scale(.98); }
</style>
</head>
<body>
  <div class="wrap">
    <img class="logo" alt="ElvoControll" src="data:image/png;base64,">
    <h1>Ste offline</h1>
    <p>Zariadenie nemá pripojenie k sieti. Pripojte sa k Wi-Fi alebo mobilným dátam a skúste to znova.</p>
    <p class="hint">Stránka sa obnoví automaticky po obnovení pripojenia.</p>
    <button id="retry">Skúsiť znova</button>
  </div>
  <script>
    // Po obnoveni siete (alebo kliki na „Skusit znova") ta sa presmeruje na normalnu appku.
    // Nacita sviezu stranku zo siete (SW fetch teraz prejde), nie offline fallback.
    function goApp() { location.replace(location.origin + '/'); }
    window.addEventListener('online', goApp);
    document.getElementById('retry').addEventListener('click', goApp);
  </script>
</body>
</html>`;

const OFFLINE_RESPONSE = () => new Response(OFFLINE_HTML, {
    status: 200,
    headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' }
});

// Staticke subory -> cache-first (hned, bez cakania na siet)
const STATIC_PATTERNS = [
    /fonts\.googleapis\.com/, /fonts\.gstatic\.com/,
    /unpkg\.com/, /cdn\.jsdelivr\.net/,
    /\/templates\/.+\.(png|svg|jpg|ico|css|js)$/,
    /\/manifest\.json$/
];

self.addEventListener('install', e => { self.skipWaiting(); });
self.addEventListener('activate', e => {
    e.waitUntil(
        caches.keys().then(names => Promise.all(
            names.map(n => caches.delete(n))  // VYMAZE VSETKY cache (aj aktualnu) — cisty start
        )).then(() => clients.claim())
    );
});

// Obnova push subscription — Chrome/Android obcas zmeni token (update prehliadaca),
// bez tejto udalosti by notifikacie po case umreli. Novy token sa samodosle na server.
self.addEventListener('pushsubscriptionchange', (event) => {
    event.waitUntil(
        self.registration.pushManager.subscribe(
            (event.oldSubscription && event.oldSubscription.options)
                ? event.oldSubscription.options
                : { userVisibleOnly: true, applicationServerKey: undefined }
        )
        .catch(() => null)
        .then(async (newSubscription) => {
            if (!newSubscription) return;
            // Posli novy token na backend (cookie -> credentials include)
            try {
                await fetch('/api/push/subscribe', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'include',
                    body: JSON.stringify(newSubscription.toJSON())
                });
            } catch (e) { /* skusime pri dalsej udalosti */ }
            // Ak zmena vznikla zo starej subscription, backend si mrtvy endpoint
            // vycisti automaticky pri prvom push (410 Gone handler)
        })
    );
});

self.addEventListener('push', e => {
    const data = e.data ? e.data.json() : { title: 'ElvoControll', body: 'Notifikácia' };
    const isAlert = (data.tag || '').startsWith('alert-');
    e.waitUntil(self.registration.showNotification(data.title, {
        body: data.body,
        icon: '/templates/ElvosolarLogo.png',
        badge: '/templates/ElvosolarLogo.png',
        vibrate: [200, 100, 200, 100, 200],
        tag: data.tag || 'elvo-notification',
        renotify: true,
        requireInteraction: isAlert,
        silent: false,
        data: { url: data.url || '/' }
    }));
});

self.addEventListener('notificationclick', e => {
    e.notification.close();
    e.waitUntil(clients.openWindow(e.notification.data.url));
});

self.addEventListener('fetch', e => {
    const req = e.request;
    if (req.method !== 'GET') return;
    const url = req.url;
    // API nikdy necachujeme (vzdy cerstve data)
    if (url.includes('/api/') || url.includes('/healthcheck')) return;
    // NAVIGACIA (otvorenie PWA / preklik) — bez siete ukazuj offline obrazovku.
    // Data sa NECACHUJU, takze ziadna stará verzia dashboardu; len „offline" fallback.
    if (req.mode === 'navigate') {
        e.respondWith(
            fetch(req).catch(() => OFFLINE_RESPONSE())
        );
        return;
    }
    const isStatic = STATIC_PATTERNS.some(rx => rx.test(url));
    if (!isStatic) return;
    e.respondWith(
        caches.match(req).then(hit => {
            if (hit) {
                // aktualizuj v pozadi (stale-while-revalidate)
                fetch(req).then(res => {
                    if (res && res.ok) {
                        const cl = caches.open(CACHE_NAME);
                        cl.then(cache => cache.put(req, res));
                    }
                }).catch(() => {});
                return hit;
            }
            return fetch(req).then(res => {
                if (res && res.ok) {
                    const clone = res.clone();
                    caches.open(CACHE_NAME).then(cache => cache.put(req, clone));
                }
                return res;
            }).catch(() => hit);
        })
    );
});
